"""Tests for snake.controls module."""

import pytest
from snake.controls import key_to_direction


class TestArrowKeyCodes:
    """Test mapping of curses arrow key codes."""

    def test_key_up_maps_to_up(self):
        """Arrow up key maps to 'up' direction."""
        result = key_to_direction("KEY_UP")  # We'll use the actual constant value
        assert result == "up"


class TestWASDKeys:
    """Test mapping of WASD keys."""

    def test_w_maps_to_up(self):
        """w key maps to 'up' direction."""
        assert key_to_direction("w") == "up"

    def test_a_maps_to_left(self):
        """a key maps to 'left' direction."""
        assert key_to_direction("a") == "left"

    def test_s_maps_to_down(self):
        """s key maps to 'down' direction."""
        assert key_to_direction("s") == "down"

    def test_d_maps_to_right(self):
        """d key maps to 'right' direction."""
        assert key_to_direction("d") == "right"


class TestNumpadKeys:
    """Test mapping of numpad-style keys (k/h/j/l)."""

    def test_k_maps_to_up(self):
        """k key maps to 'up' direction."""
        assert key_to_direction("k") == "up"

    def test_h_maps_to_left(self):
        """h key maps to 'left' direction."""
        assert key_to_direction("h") == "left"

    def test_j_maps_to_down(self):
        """j key maps to 'down' direction."""
        assert key_to_direction("j") == "down"

    def test_l_maps_to_right(self):
        """l key maps to 'right' direction."""
        assert key_to_direction("l") == "right"


class TestCaseInsensitivity:
    """Test that keys are case-insensitive."""

    def test_w_uppercase_maps_to_up(self):
        """W (uppercase) maps to 'up' direction."""
        assert key_to_direction("W") == "up"

    def test_a_uppercase_maps_to_left(self):
        """A (uppercase) maps to 'left' direction."""
        assert key_to_direction("A") == "left"

    def test_s_uppercase_maps_to_down(self):
        """S (uppercase) maps to 'down' direction."""
        assert key_to_direction("S") == "down"

    def test_d_uppercase_maps_to_right(self):
        """D (uppercase) maps to 'right' direction."""
        assert key_to_direction("D") == "right"


class TestInvalidKeys:
    """Test that invalid keys return None."""

    def test_invalid_string_returns_none(self):
        """Invalid string input returns None."""
        assert key_to_direction("x") is None
        assert key_to_direction(" ") is None
        assert key_to_direction("") is None

    def test_number_returns_none(self):
        """Numeric input that isn't a recognized code returns None."""
        assert key_to_direction(97) is None  # ASCII for 'a' as int, not KEY constants

    def test_large_number_returns_none(self):
        """Arbitrary large number returns None."""
        assert key_to_direction(999) is None


class TestDirectionOutputs:
    """Test that all valid directions can be produced."""

    def test_all_four_directions_possible(self):
        """All four directions can be mapped from valid inputs."""
        assert key_to_direction("w") == "up"
        assert key_to_direction("a") == "left"
        assert key_to_direction("s") == "down"
        assert key_to_direction("d") == "right"
